"""Regenerate nav-icons.js from the portal's own icon source.

Run from the repo root:  python3 -I "Design/portal-ui-kit/sync-icons.py"
Reads src/lib/nav/nav-icons.ts and writes Design/portal-ui-kit/nav-icons.js, so
mockups draw exactly the icons the rail and panels draw.
"""
import json
import pathlib
import re

root = pathlib.Path.cwd()
src = (root / 'src/lib/nav/nav-icons.ts').read_text(encoding='utf8')
icons = dict(re.findall(r"'([a-z0-9-]+)':\s*'([^']+)'", src))
out = root / 'Design/portal-ui-kit/nav-icons.js'
out.write_text(
    '// Generated by sync-icons.py from src/lib/nav/nav-icons.ts. Do not edit by hand.\n'
    'window.NAV_ICON = ' + json.dumps(icons, indent=1) + ';\n'
    'window.navIcon = function (name, cls) {\n'
    "  return '<svg class=\"navicon' + (cls ? ' ' + cls : '') + '\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"' + (window.NAV_ICON[name] || '') + '\"/></svg>';\n"
    '};\n',
    encoding='utf8',
)
print(f'{len(icons)} icons -> {out}')
